/**
 * Shared SLST branded email layout — light + dark (prefers-color-scheme).
 * Light matches cream concept cards; dark matches charcoal concept cards.
 */
export const DEFAULT_EMAIL_ASSET_BASE =
  "https://gdrpdiwykmnybmkadlrv.supabase.co/storage/v1/object/public/email-assets";

const BRAND = "#D93223";
const BRAND_DARK = "#B8281C";
const ORANGE = "#E67E22";
const BLUE = "#5B9BD5";

// Light theme
const L_INK = "#2A2A2A";
const L_BODY = "#3A3A3A";
const L_MUTED = "#6B6B6B";
const L_BORDER = "#E6E2DC";
const L_PAGE = "#F3F1EC";
const L_SHELL = "#FFFFFF";
const L_CARD = "#F7F5F1";
const L_ICON = "#FDECEA";
const WHITE = "#FFFFFE";

// Dark theme (concept photo 3)
const D_INK = "#F5F5F5";
const D_BODY = "#D8D8D8";
const D_MUTED = "#A0A0A0";
const D_BORDER = "#3A3A3A";
const D_PAGE = "#1A1A1A";
const D_SHELL = "#2A2A2A";
const D_CARD = "#242424";
const D_ICON = "#3A2A28";

const IMP = "!important";
const ASSET_VERSION = "20260725a";
const FONT_STACK = "'Oswald', Arial, Helvetica, sans-serif";
const FONT_LINK =
  "https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&display=swap";

const DISCLAIMER_HTML =
  "SLST is an internal operations tool for Swift Nisku warehouse staff. It helps us record what is staged, what is ready to ship, and what has left the building—and to notify sales when orders depart. It is not a carrier tracking system, proof-of-delivery tool, or comprehensive order-tracking platform. Expectations beyond this operational purpose fall outside the scope of the application.";

function bg(color: string): string {
  return `background-color:${color} ${IMP};`;
}

function fg(color: string): string {
  return `color:${color} ${IMP};`;
}

export function surfaceBg(color: string): string {
  return `${bg(color)} background-image:linear-gradient(${color},${color}) ${IMP};`;
}

/** Dual-theme CSS: light defaults + dark prefers-color-scheme / Outlook dark. */
export function themeCss(): string {
  const ctaGrad = `linear-gradient(${BRAND},${BRAND_DARK})`;
  return `
    :root, html { color-scheme: light dark ${IMP}; supported-color-schemes: light dark ${IMP}; }
    .logo-dark { display: none ${IMP}; max-height: 0 ${IMP}; overflow: hidden ${IMP}; }
    .logo-light { display: block ${IMP}; }
    @media (prefers-color-scheme: dark) {
      .og-page { ${bg(D_PAGE)} background-image:linear-gradient(${D_PAGE},${D_PAGE}) ${IMP}; }
      .og-shell, .og-footer { ${bg(D_SHELL)} background-image:linear-gradient(${D_SHELL},${D_SHELL}) ${IMP}; }
      .og-white, .og-card { ${bg(D_CARD)} background-image:linear-gradient(${D_CARD},${D_CARD}) ${IMP}; }
      .og-icon { ${bg(D_ICON)} background-image:linear-gradient(${D_ICON},${D_ICON}) ${IMP}; }
      .og-text, .og-text strong, .og-text h1 { ${fg(D_INK)} }
      .og-body { ${fg(D_BODY)} }
      .og-muted { ${fg(D_MUTED)} }
      .og-brand { ${fg(ORANGE)} }
      .og-border { border-color:${D_BORDER} ${IMP}; }
      .og-cta, .og-cta span {
        ${fg(WHITE)} border-color:${BRAND} ${IMP};
        ${bg(BRAND)} background-image:${ctaGrad} ${IMP};
      }
      .logo-light { display: none ${IMP}; max-height: 0 ${IMP}; overflow: hidden ${IMP}; width: 0 ${IMP}; height: 0 ${IMP}; }
      .logo-dark { display: block ${IMP}; max-height: none ${IMP}; overflow: visible ${IMP}; }
    }
    /* Outlook.com / Office dark-mode hooks */
    [data-ogsb] .og-page, [data-ogab] .og-page { ${bg(D_PAGE)} }
    [data-ogsb] .og-shell, [data-ogsb] .og-footer, [data-ogab] .og-shell { ${bg(D_SHELL)} }
    [data-ogsb] .og-white, [data-ogsb] .og-card, [data-ogab] .og-white { ${bg(D_CARD)} }
    [data-ogsc] .og-text, [data-ogac] .og-text { ${fg(D_INK)} }
    [data-ogsc] .og-body, [data-ogac] .og-body { ${fg(D_BODY)} }
    [data-ogsc] .og-muted, [data-ogac] .og-muted { ${fg(D_MUTED)} }
    [data-ogsc] .og-brand, [data-ogac] .og-brand { ${fg(ORANGE)} }
  `;
}

export function emailAssetUrl(fileKey: string, baseUrl?: string): string {
  const base = (baseUrl ?? DEFAULT_EMAIL_ASSET_BASE).replace(/\/$/, "");
  const key = fileKey.replace(/\.png$/i, "");
  if (base.includes("/functions/v1/email-assets")) {
    return `${base}?f=${encodeURIComponent(key)}&v=${ASSET_VERSION}`;
  }
  return `${base}/${encodeURIComponent(key)}.png?v=${ASSET_VERSION}`;
}

export function esc(value: string | undefined | null): string {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

export function displayOrNone(value: string | undefined | null): string {
  const v = String(value ?? "").trim();
  return v.length ? esc(v) : "None";
}

export function detailCard(opts: {
  iconUrl: string;
  title: string;
  accent: "orange" | "blue";
  rows: Array<{ label: string; value: string }>;
}): string {
  const accent = opts.accent === "blue" ? BLUE : ORANGE;
  const whiteSurf = surfaceBg(L_CARD);
  const iconSurf = surfaceBg(L_ICON);
  const rowsHtml = opts.rows
    .map(
      (r) => `
        <tr>
          <td class="og-text og-card" style="padding:0 0 10px 0;font-family:${FONT_STACK};font-size:14px;line-height:1.35;${whiteSurf}">
            <div class="og-text" style="font-weight:700;color:${L_INK};mso-line-height-rule:exactly;">
              ${esc(r.label)}
            </div>
            <div class="og-body" style="font-weight:400;padding-top:2px;color:${L_BODY};mso-line-height-rule:exactly;">
              ${r.value}
            </div>
          </td>
        </tr>`,
    )
    .join("");
  return `
    <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" class="og-card og-border"
      style="${whiteSurf} border:2px solid ${L_BORDER};border-radius:14px;border-top:4px solid ${accent};box-shadow:0 4px 14px rgba(42,42,42,0.06);">
      <tr>
        <td class="og-card" style="padding:20px 18px 12px 18px;${whiteSurf}">
          <table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%">
            <tr>
              <td width="44" valign="top" style="padding-right:12px;${whiteSurf}">
                <table role="presentation" cellpadding="0" cellspacing="0" border="0" width="40" height="40" class="og-icon"
                  style="width:40px;height:40px;${iconSurf} border-radius:10px;">
                  <tr>
                    <td align="center" valign="middle" class="og-icon"
                      style="width:40px;height:40px;text-align:center;vertical-align:middle;${iconSurf}">
                      <img src="${esc(opts.iconUrl)}" width="24" height="24" alt=""
                        style="display:block;margin:0 auto;border:0;outline:none;-ms-interpolation-mode:bicubic;" />
                    </td>
                  </tr>
                </table>
              </td>
              <td valign="middle" class="og-brand" style="${whiteSurf}">
                <div class="og-brand" style="font-family:${FONT_STACK};font-size:12px;font-weight:700;letter-spacing:0.12em;text-transform:uppercase;color:${accent};mso-line-height-rule:exactly;">
                  ${esc(opts.title)}
                </div>
              </td>
            </tr>
          </table>
          <table role="presentation" cellpadding="0" cellspacing="0" border="0" width="100%" style="margin-top:14px;">
            ${rowsHtml}
          </table>
        </td>
      </tr>
    </table>`;
}

export function headerLogosBlock(
  swiftLogoUrl: string,
  slstLogoLightUrl: string,
  slstLogoDarkUrl: string,
): string {
  const rowHeight = 124;
  return `<table role="presentation" cellpadding="0" cellspacing="0" border="0" align="center" class="logo-row" style="margin:0 auto;width:100%;">
    <tr>
      <td align="center" valign="middle" style="vertical-align:middle;text-align:center;padding:0;">
        <table role="presentation" cellpadding="0" cellspacing="0" border="0" align="center" style="margin:0 auto;">
          <tr>
            <td align="center" valign="middle" height="${rowHeight}" style="vertical-align:middle;text-align:center;padding:0 16px 0 0;height:${rowHeight}px;">
              <img class="logo-swift" src="${esc(swiftLogoUrl)}" width="200" height="62" alt="Swift Supply"
                style="display:block;margin:0 auto;border:0;outline:none;width:200px;max-width:38vw;height:auto;vertical-align:middle;-ms-interpolation-mode:bicubic;" />
            </td>
            <td align="center" valign="middle" height="${rowHeight}" style="vertical-align:middle;text-align:center;padding:0 12px;height:${rowHeight}px;font-family:${FONT_STACK};font-size:28px;font-weight:300;color:${L_MUTED};">
              +
            </td>
            <td align="center" valign="middle" height="${rowHeight}" style="vertical-align:middle;text-align:center;padding:0 0 0 8px;height:${rowHeight}px;">
              <img class="logo-img logo-light" src="${esc(slstLogoLightUrl)}" width="260" height="124" alt="SLST — Staging Log &amp; Shipping Tracker"
                style="display:block;margin:0 auto;border:0;outline:none;width:260px;max-width:46vw;height:auto;vertical-align:middle;-ms-interpolation-mode:bicubic;" />
              <img class="logo-img logo-dark" src="${esc(slstLogoDarkUrl)}" width="260" height="124" alt="SLST — Staging Log &amp; Shipping Tracker"
                style="display:none;margin:0 auto;border:0;outline:none;width:260px;max-width:46vw;height:auto;vertical-align:middle;-ms-interpolation-mode:bicubic;" />
            </td>
          </tr>
        </table>
      </td>
    </tr>
  </table>`;
}

function attachmentsSection(
  attachmentUrls: string[],
  assetBase: string,
): string {
  if (!attachmentUrls.length) return "";
  const cargo = emailAssetUrl("icon-cargo", assetBase);
  const gallery = attachmentUrls.slice(0, 8).map((url, i) => `
    <tr>
      <td style="padding:8px 0;">
        <a href="${esc(url)}" style="text-decoration:none;">
          <img src="${esc(url)}" width="520" alt="Attachment ${i + 1}"
            style="display:block;width:100%;max-width:520px;height:auto;border-radius:10px;border:2px solid ${L_BORDER};" />
        </a>
      </td>
    </tr>`).join("");
  return `
    <tr>
      <td class="og-shell" style="padding:0 22px 10px 22px;${surfaceBg(L_SHELL)}">
        ${detailCard({
          iconUrl: cargo,
          title: "ATTACHMENTS",
          accent: "orange",
          rows: [{
            label: "Files",
            value: `${attachmentUrls.length} attached image${attachmentUrls.length === 1 ? "" : "s"}`,
          }],
        })}
        <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" style="margin-top:12px;">
          ${gallery}
        </table>
      </td>
    </tr>`;
}

export type BrandedEmailOptions = {
  title: string;
  preview: string;
  subtitle?: string;
  cards: Array<{
    iconKey: string;
    title: string;
    accent?: "orange" | "blue";
    rows: Array<{ label: string; value: string }>;
  }>;
  attachmentUrls?: string[];
  assetBaseUrl?: string;
  logoUrl?: string;
  ctaUrl?: string;
  ctaLabel?: string;
  emailContact?: string;
  websiteUrl?: string;
  year?: number;
};

export function renderBrandedEmail(opts: BrandedEmailOptions): string {
  const assetBase = opts.assetBaseUrl ?? DEFAULT_EMAIL_ASSET_BASE;
  const slstLight = (opts.logoUrl && opts.logoUrl.trim()) ||
    emailAssetUrl("slst-logo-email", assetBase);
  const slstDark = emailAssetUrl("slst-logo-email-dark", assetBase);
  const swiftLogoUrl = emailAssetUrl("swift-supply-logo-email", assetBase);
  const title = esc(opts.title);
  const subtitle = esc(opts.subtitle ?? "");
  const preview = esc(opts.preview);
  const year = opts.year ?? new Date().getFullYear();
  const emailContact = (opts.emailContact ?? "warehouse1@swiftsupply.ca").trim();
  const mailto = `mailto:${emailContact}`;
  const website = (opts.websiteUrl ?? "https://www.swiftsupply.ca").trim();
  const mail = emailAssetUrl("icon-mail", assetBase);
  const webIcon = emailAssetUrl("icon-mail", assetBase);
  const pageSurf = surfaceBg(L_PAGE);
  const shellSurf = surfaceBg(L_SHELL);
  const attachmentUrls = opts.attachmentUrls ?? [];
  const ctaUrl = (opts.ctaUrl ?? "").trim();
  const ctaLabel = esc(opts.ctaLabel ?? "VIEW FULL TRACKING DETAILS");

  const cardHtml = opts.cards.map((card, i) => {
    const accent = card.accent ?? (i % 2 === 0 ? "orange" : "blue");
    const html = detailCard({
      iconUrl: emailAssetUrl(card.iconKey, assetBase),
      title: card.title,
      accent,
      rows: card.rows,
    });
    return { html, col: i % 2 === 0 ? "left" : "right", row: Math.floor(i / 2) };
  });

  const rowsByIndex = new Map<number, string[]>();
  for (const item of cardHtml) {
    const row = rowsByIndex.get(item.row) ?? [];
    row.push(`
      <td class="stack-col stack-col-pad" width="50%" valign="top" style="width:50%;padding:8px;">
        ${item.html}
      </td>`);
    rowsByIndex.set(item.row, row);
  }
  const cardsTable = [...rowsByIndex.entries()]
    .sort(([a], [b]) => a - b)
    .map(([, cols]) =>
      `<tr>${cols.join("")}${
        cols.length === 1
          ? '<td class="stack-col" width="50%" style="width:50%;padding:8px;"></td>'
          : ""
      }</tr>`
    )
    .join("");

  const ctaBlock = ctaUrl
    ? `
          <tr>
            <td align="center" class="og-shell" style="padding:8px 36px 22px 36px;${shellSurf}">
              <a class="og-cta" href="${esc(ctaUrl)}"
                style="display:inline-block;padding:14px 28px;border-radius:999px;font-family:${FONT_STACK};font-size:14px;font-weight:700;letter-spacing:0.04em;text-decoration:none;color:${WHITE};${bg(BRAND)} background-image:linear-gradient(${BRAND},${BRAND_DARK});">
                🔍 ${ctaLabel}
              </a>
            </td>
          </tr>`
    : "";

  return `<!DOCTYPE html>
<html lang="en" xmlns="http://www.w3.org/1999/xhtml" xmlns:v="urn:schemas-microsoft-com:vml" xmlns:o="urn:schemas-microsoft-com:office:office" style="color-scheme:light dark;">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <meta http-equiv="X-UA-Compatible" content="IE=edge" />
  <meta name="color-scheme" content="light dark" />
  <meta name="supported-color-schemes" content="light dark" />
  <meta name="x-apple-disable-message-reformatting" />
  <title>${title}</title>
  <link href="${FONT_LINK}" rel="stylesheet" type="text/css" />
  <!--[if mso]>
  <noscript>
    <xml>
      <o:OfficeDocumentSettings>
        <o:PixelsPerInch>96</o:PixelsPerInch>
        <o:AllowPNG/>
      </o:OfficeDocumentSettings>
    </xml>
  </noscript>
  <style>
    table { border-collapse: collapse; }
    td, th, div, p, a, span, strong, h1 { font-family: ${FONT_STACK} !important; }
  </style>
  <![endif]-->
  <style type="text/css">
    :root { color-scheme: light dark !important; supported-color-schemes: light dark !important; }
    body, table, td, a { -webkit-text-size-adjust: 100%; -ms-text-size-adjust: 100%; }
    table, td { mso-table-lspace: 0pt; mso-table-rspace: 0pt; }
    img { -ms-interpolation-mode: bicubic; border: 0; outline: none; text-decoration: none; }
    body { margin: 0 !important; padding: 0 !important; width: 100% !important; ${surfaceBg(L_PAGE)} }
    a { ${fg(BRAND)} }
    ${themeCss()}
    @media only screen and (max-width: 620px) {
      .email-card { width: 100% !important; }
      .stack-col { display: block !important; width: 100% !important; max-width: 100% !important; box-sizing: border-box !important; padding-left: 0 !important; padding-right: 0 !important; }
      .stack-col-pad { padding: 8px 0 !important; }
      .footer-right { text-align: left !important; padding-top: 16px !important; }
      .logo-swift { width: 140px !important; max-width: 36vw !important; height: auto !important; }
      .logo-img { width: 190px !important; max-width: 48vw !important; height: auto !important; }
    }
  </style>
</head>
<body class="body og-page" style="margin:0;padding:0;${pageSurf}">
  <div style="display:none;max-height:0;overflow:hidden;mso-hide:all;font-size:1px;line-height:1px;${fg(L_PAGE)}">
    ${preview}
  </div>
  <table role="presentation" class="og-page" width="100%" cellpadding="0" cellspacing="0" border="0"
    style="${pageSurf}">
    <tr>
      <td align="center" class="og-page" style="padding:36px 16px 28px 16px;${pageSurf}">
        <!--[if mso]>
        <table role="presentation" width="600" cellpadding="0" cellspacing="0" border="0"><tr><td>
        <![endif]-->
        <table role="presentation" class="email-card og-shell og-border" width="600" cellpadding="0" cellspacing="0" border="0"
          style="width:100%;max-width:600px;${shellSurf} border-radius:18px;border:2px solid ${L_BORDER};box-shadow:0 18px 48px rgba(42,42,42,0.10);overflow:hidden;">
          <tr>
            <td align="center" class="og-shell" style="padding:42px 28px 10px 28px;${shellSurf}">
              ${headerLogosBlock(swiftLogoUrl, slstLight, slstDark)}
            </td>
          </tr>
          <tr>
            <td align="center" class="og-shell og-text" style="padding:26px 36px 6px 36px;${shellSurf}">
              <h1 class="og-text" style="margin:0;font-family:${FONT_STACK};font-size:28px;line-height:1.28;font-weight:700;color:${L_INK};">
                ${title}
              </h1>
            </td>
          </tr>
          ${subtitle ? `
          <tr>
            <td align="center" class="og-shell og-text" style="padding:8px 36px 26px 36px;${shellSurf}">
              <p class="og-body" style="margin:0;font-family:${FONT_STACK};font-size:16px;line-height:1.4;color:${L_BODY};">
                ${subtitle}
              </p>
            </td>
          </tr>` : ""}
          <tr>
            <td class="og-shell" style="padding:0 22px 10px 22px;${shellSurf}">
              <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
                ${cardsTable}
              </table>
            </td>
          </tr>
          ${attachmentsSection(attachmentUrls, assetBase)}
          ${ctaBlock}
          <tr>
            <td class="og-shell" style="padding:0 36px;${shellSurf}">
              <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
                <tr>
                  <td class="og-shell og-border" style="border-top:2px solid ${L_BORDER};font-size:0;line-height:0;${shellSurf}">&nbsp;</td>
                </tr>
              </table>
            </td>
          </tr>
          <tr>
            <td class="og-shell og-footer" style="padding:22px 36px 32px 36px;${shellSurf}">
              <table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0">
                <tr>
                  <td class="stack-col og-text" valign="top"
                    style="font-family:${FONT_STACK};font-size:13px;line-height:1.55;${shellSurf}">
                    <strong class="og-text" style="font-weight:700;color:${L_INK};">Thank you for using SLST!</strong><br />
                    <span class="og-body" style="color:${L_BODY};">SLST - Staging Log &amp; Shipping Tracker</span><br />
                    <span class="og-muted" style="font-size:12px;color:${L_MUTED};">Copyright © ${year} SLST. All rights reserved.</span>
                  </td>
                  <td class="stack-col footer-right" valign="middle" align="right"
                    style="font-family:${FONT_STACK};font-size:13px;line-height:1.9;white-space:nowrap;${shellSurf}">
                    <a class="og-brand" href="${esc(mailto)}" style="text-decoration:underline;color:${BRAND};">
                      <img src="${esc(mail)}" width="14" height="14" alt=""
                        style="display:inline-block;vertical-align:middle;margin-right:5px;border:0;" />
                      Email
                    </a>
                    &nbsp;&nbsp;
                    <a class="og-brand" href="${esc(website)}" style="text-decoration:underline;color:${BRAND};">
                      <img src="${esc(webIcon)}" width="14" height="14" alt=""
                        style="display:inline-block;vertical-align:middle;margin-right:5px;border:0;" />
                      Website
                    </a>
                  </td>
                </tr>
              </table>
            </td>
          </tr>
        </table>
        <!--[if mso]>
        </td></tr></table>
        <![endif]-->
        <div class="og-muted" style="font-family:${FONT_STACK};font-size:11px;padding-top:18px;color:${L_MUTED};">
          Sent via SLST · Swift Supply
        </div>
      </td>
    </tr>
  </table>
</body>
</html>`;
}

export { BRAND };
// Back-compat aliases used by older imports
export const darkModeCss = themeCss;
export const PAGE_BG = L_PAGE;
export const CARD_SHELL = L_SHELL;
export const INK = L_INK;
export const BODY = L_BODY;
export const MUTED = L_MUTED;
export const BORDER = L_BORDER;
export { WHITE };
